import React, { useCallback, useEffect, useRef, useState } from 'react';
type Renderer = (onFirstDraw: () => void) => React.ReactNode;

/** Native stacks keep inactive screens mounted. A stopped frame loop still owns a
 * GL context, textures and render targets. Mount the renderer only while visible
 * and foregrounded; the persistent seed and growth history remain outside it.
 * Each activation owns its first-draw callback and watchdog, so a late callback
 * from a disposed context cannot approve a different instance.
  children: Renderer;
  const [failed, setFailed] = useState(false);
  const abandon = useCallback(() => setFailed(true), []);
  return <View style={{ flex: 1 }} testID="plant-render-surface" accessible={false}>
    {failed ? <Alternative phase="simplified">{fallback}</Alternative>
      : active ? <VisibleSurface fallback={fallback} renderer={children} onFailure={abandon}/>
      : <Alternative phase="paused">{fallback}</Alternative>}
  </View>;
}

function Alternative({phase, children}: {
  phase: 'starting' | 'simplified' | 'paused'; children: React.ReactNode;
}) {
  return <>
    <View style={StyleSheet.absoluteFill} pointerEvents="none" testID="plant-procedural-alternative">
      {children}
      <Text style={{ color: '#B8C2BE', fontSize: 10, textAlign: 'center' }}>
        {phase === 'starting' ? 'Preparando vista 3D'
          : phase === 'paused' ? 'Vista 3D en pausa' : 'Vista procedural simplificada'}
      </Text>
    </View>
    <View testID={'plant-render-' + phase} style={{ width: 1, height: 1 }} accessible={false}/>
  </>;
}

function VisibleSurface({ fallback, renderer, onFailure }: {
  fallback: React.ReactNode; renderer: Renderer; onFailure: () => void;
}) {
  const [drawing, setDrawing] = useState(false);
  const alive = useRef(true);
    alive.current = true;
    return () => { alive.current = false; };
  }, []);
  const firstDraw = useCallback(() => {
    if (alive.current) setDrawing(true);
  }, []);
  useEffect(() => {
    if (drawing) return;
    const timer = setTimeout(() => { if (alive.current) onFailure(); }, 7000);
  }, [drawing, onFailure]);
  return <>
    <View style={StyleSheet.absoluteFill} pointerEvents="none" accessible={false}>
      <RendererBoundary onFailure={onFailure}>{renderer(firstDraw)}</RendererBoundary>
    </View>
    {drawing ? <View testID="plant-render-drawing" style={{width:1,height:1}} accessible={false}/>
      : <Alternative phase="starting">{fallback}</Alternative>}
  </>;

  expect(screen.getByTestId('plant-render-paused')).toBeTruthy();
  expect(screen.queryByText('GPU instance')).toBeNull();

test('an inactive native screen never creates a renderer, even during preload', () => {
  const renderGPU=jest.fn<(_:()=>void)=>React.ReactNode>(()=><Text>GPU instance</Text>);
  render(<PlantSurface active={false} fallback={seedView}>{renderGPU}</PlantSurface>);
  expect(renderGPU).not.toHaveBeenCalled();
  expect(screen.getByTestId('plant-render-paused')).toBeTruthy();
  expect(jest.getTimerCount()).toBe(0);
});
test('focus loss disposes the mounted scene and returning requires a fresh draw', () => {
  let mounted=0,disposed=0;
  let lastDraw!:()=>void;
  function GPU(){React.useEffect(()=>{mounted++;return()=>{disposed++}},[]);return <Text>GPU instance</Text>}
  const renderer=(draw:()=>void)=>{lastDraw=draw;return <GPU/>};
  const view=render(<PlantSurface active fallback={seedView}>{renderer}</PlantSurface>);
  const oldDraw=lastDraw;
  act(()=>oldDraw());expect(mounted).toBe(1);
  view.rerender(<PlantSurface active={false} fallback={seedView}>{renderer}</PlantSurface>);
  expect(disposed).toBe(1);expect(screen.queryByText('GPU instance')).toBeNull();
  expect(jest.getTimerCount()).toBe(0);
  view.rerender(<PlantSurface active fallback={seedView}>{renderer}</PlantSurface>);
  expect(mounted).toBe(2);expect(screen.getByTestId('plant-render-starting')).toBeTruthy();
  act(()=>oldDraw());expect(screen.getByTestId('plant-render-starting')).toBeTruthy();
  act(()=>lastDraw());expect(screen.getByTestId('plant-render-drawing')).toBeTruthy();
  view.unmount();expect(disposed).toBe(2);
});
test('an abandoned native context is not retried repeatedly when focus changes', () => {
  const renderer=jest.fn<(_:()=>void)=>React.ReactNode>(()=><Text>GPU instance</Text>);
  const view=render(<PlantSurface active fallback={seedView}>{renderer}</PlantSurface>);
  act(()=>jest.advanceTimersByTime(7000));const calls=renderer.mock.calls.length;
  view.rerender(<PlantSurface active={false} fallback={seedView}>{renderer}</PlantSurface>);
  view.rerender(<PlantSurface active fallback={seedView}>{renderer}</PlantSurface>);
  expect(renderer.mock.calls).toHaveLength(calls);
  expect(screen.getByTestId('plant-render-simplified')).toBeTruthy();
  expect(screen.getByText('Same seed and growth stage')).toBeTruthy();
});
